import sys

def count_primes(n: int) -> int:
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * (n // 2)
    sieve[0] = 0
    limit = int((n - 1) ** 0.5)
    for i in range(1, limit // 2 + 1):
        if sieve[i]:
            p = 2 * i + 1
            start = (p * p) // 2
            sieve[start::p] = bytearray(((n // 2 - 1 - start) // p) + 1)
    return sieve.count(1) + 1

if __name__ == '__main__':
    print(count_primes(int(sys.argv[1])))
